mapper.update:
UPDATE ai_theme_draft_request_intent SET state='PROCESSING', claim_token=#{claimToken},
    claimed_at=#{now}, updated_at=#{now}
WHERE id=#{id} AND member_id=#{memberId} AND request_hash=#{requestHash} AND plan_hash=#{planHash}
  AND state='PREPARED' AND claim_token IS NULL

mapper.select:
SELECT id,member_id,prepare_key,request_id,state,reason_code,created_at,execute_before,result_expires_at,product_type
FROM ai_theme_draft_request_intent FORCE INDEX(idx_atdi_v2_recovery)
WHERE member_id=#{memberId}
AND id<#{beforeId}
ORDER BY id DESC LIMIT 21

mapper.update:
UPDATE ai_theme_draft_request_intent SET state='FAILED', provider_state='NOT_SENT', reason_code=#{reasonCode},
    outcome_hash=#{outcomeHash}, completed_at=#{completedAt}, updated_at=#{completedAt}
WHERE id=#{id} AND member_id=#{memberId} AND request_hash=#{requestHash} AND plan_hash=#{planHash}
  AND state='PREPARED' AND claim_token IS NULL

UPDATE ai_theme_draft_request_intent SET state=#{state}, provider_state=#{providerState}, reason_code=#{reasonCode},
    result_hash=#{resultHash}, outcome_hash=#{outcomeHash}, result_expires_at=#{resultExpiresAt},
    completed_at=#{completedAt}, updated_at=#{completedAt}
WHERE id=#{id} AND member_id=#{memberId} AND request_hash=#{requestHash} AND plan_hash=#{planHash}
  AND nonce=#{nonce} AND claim_token=#{claimToken} AND state='PROCESSING'
